mapper.sql:
from qms_ocap_item o

    o.rule_cd is null
    o.rule_cd = #{rule}
    and o.use_yn = #{useYn}
    and o.action_text ilike #{kw} escape '\'

mapper.update:
update qms_ocap_item
   set rule_cd = #{f.ruleCd}, seq = #{f.seq}, action_text = #{f.actionText}, use_yn = #{f.useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where ocap_id = #{id} and row_ver = #{f.rowVer}
